-- Amostra visual de cada estilo (a miniatura do banco, em base64), enviada à IA de imagem como
-- referência de técnica. Só o service role lê: não entra no grant de colunas do app.
begin;
alter table comic_styles add column if not exists sample text;
update comic_styles set sample = '' where id = 'aquarela-nanquim';
update comic_styles set sample = '' where id = 'fantasia-epica';
update comic_styles set sample = '' where id = 'fantasia-sombria';
update comic_styles set sample = '' where id = 'terror-gotico';
update comic_styles set sample = '' where id = 'ficcao-cientifica';
update comic_styles set sample = '' where id = 'cyberpunk';
update comic_styles set sample = '' where id = 'romance-aquarela';
update comic_styles set sample = '' where id = 'pintura-historica';
update comic_styles set sample = '' where id = 'noir-misterio';
update comic_styles set sample = '' where id = 'thriller-cinematografico';
update comic_styles set sample = '' where id = 'manga-tradicional';
update comic_styles set sample = '' where id = 'anime-colorido';
update comic_styles set sample = '' where id = 'hq-americana';
update comic_styles set sample = '' where id = 'hq-europeia';
update comic_styles set sample = '' where id = 'infantil-guache';
update comic_styles set sample = '' where id = 'realismo-magico';
do $$ begin
  if (select count(*) from comic_styles where sample is not null) <> 16 then raise exception 'esperava 16 amostras'; end if;
  if has_column_privilege('authenticated', 'comic_styles', 'sample', 'select') or has_column_privilege('anon', 'comic_styles', 'sample', 'select') then
    raise exception 'amostra visível ao app';
  end if;
end $$;
commit;
